package studio.sotto.mobile;

import java.io.*;
import java.util.*;

/** Offline English spelling. No editor text leaves the keyboard or is persisted. */
final class OfflineSpelling {
    private final Set<String> words=new HashSet<>();private final List<String> sorted;private final Map<String,Integer> common=new LinkedHashMap<>();
    private static final Map<String,String> TYPOS=new HashMap<>();
    static{String[] pairs={"teh","the","adn","and","recieve","receive","becuase","because","wierd","weird","thier","their","helllo","hello","tommorow","tomorrow","definately","definitely","seperate","separate","alot","a lot"};for(int i=0;i<pairs.length;i+=2)TYPOS.put(pairs[i],pairs[i+1]);}
    private static final String COMMON="the and to of a in is you that it for on with as are be this have from or one had by word but not what all were we when your can said there use an each which she do how their if will up other about out many then them these so some her would make like him into time has look two more write go see number no way could people my than first water been call who oil its now find long down day did get come made may part hello help please thanks thank good morning tomorrow today yesterday meeting work home message send receive because right wrong language english bangla keyboard voice text speak say know think need want should new back well very just also much where why only our here after before again still never always yes really great sure sorry okay going coming doing having let us me they he i am was does done don't I'm isn't it's that's we're you're can't won't I'll I've email friend family love school university project question answer words precise professional casual constructive prompting writing correct simple important understand start stop finish choose select settings mode recording";
    OfflineSpelling(Reader dictionary)throws IOException{int rank=0;for(String word:COMMON.split(" "))common.putIfAbsent(word.toLowerCase(Locale.ROOT),rank++);try(BufferedReader reader=new BufferedReader(dictionary)){String line;while((line=reader.readLine())!=null){String word=line.trim();if(word.length()>=2&&word.length()<=24&&asciiWord(word))words.add(word);}}words.addAll(common.keySet());sorted=new ArrayList<>(words);Collections.sort(sorted);}
    private static boolean asciiWord(String word){for(int i=0;i<word.length();i++)if(word.charAt(i)<'a'||word.charAt(i)>'z')return false;return true;}
    static String trailingWord(CharSequence before){if(before==null)return "";int end=before.length(),start=end;while(start>0){char c=before.charAt(start-1);int type=Character.getType(c);if(!Character.isLetter(c)&&c!='\''&&type!=Character.NON_SPACING_MARK&&type!=Character.COMBINING_SPACING_MARK&&type!=Character.ENCLOSING_MARK)break;start--;}return before.subSequence(start,end).toString();}
    List<String> suggestions(String input){String word=input.toLowerCase(Locale.ROOT);LinkedHashSet<String> result=new LinkedHashSet<>();if(word.isEmpty())return Arrays.asList("the","and","I");if(!word.matches("[a-z']{1,24}"))return Collections.singletonList(input);String correction=correction(input);if(!correction.equals(input))result.add(correction);result.add(input);for(String candidate:common.keySet()){if(candidate.startsWith(word)&&!candidate.equals(word)){result.add(cased(input,candidate));if(result.size()==3)return new ArrayList<>(result);}}
        int index=Collections.binarySearch(sorted,word);if(index<0)index=-index-1;for(int i=index;i<sorted.size()&&result.size()<3;i++){String candidate=sorted.get(i);if(!candidate.startsWith(word))break;if(candidate.length()<=word.length()+6)result.add(cased(input,candidate));}if(result.size()<3)for(String candidate:candidates(word)){result.add(cased(input,candidate));if(result.size()==3)break;}return new ArrayList<>(result);
    }
    String correction(String input){String word=input.toLowerCase(Locale.ROOT);if(!word.matches("[a-z]{3,24}")||input.chars().filter(Character::isUpperCase).count()>1)return input;if(TYPOS.containsKey(word))return cased(input,TYPOS.get(word));if(words.contains(word)||word.length()<4)return input;List<String> candidates=candidates(word);if(candidates.isEmpty())return input;String best=candidates.get(0);return common.containsKey(best)||candidates.size()==1?cased(input,best):input;}
    private List<String> candidates(String word){Set<String> found=new HashSet<>();for(int i=0;i<word.length();i++){add(found,word.substring(0,i)+word.substring(i+1));if(i+1<word.length())add(found,word.substring(0,i)+word.charAt(i+1)+word.charAt(i)+word.substring(i+2));for(char c='a';c<='z';c++)add(found,word.substring(0,i)+c+word.substring(i+1));}for(int i=0;i<=word.length();i++)for(char c='a';c<='z';c++)add(found,word.substring(0,i)+c+word.substring(i));List<String> result=new ArrayList<>(found);result.sort(Comparator.comparingInt((String w)->common.getOrDefault(w,10000+w.length())).thenComparing(w->w));return result;}
    private void add(Set<String> values,String candidate){if(words.contains(candidate))values.add(candidate);}
    private static String cased(String source,String target){return !source.isEmpty()&&Character.isUpperCase(source.charAt(0))?Character.toUpperCase(target.charAt(0))+target.substring(1):target;}
}
